export function safeHttps(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}}
const categories={'小吃':'Snacks','面馆':'Noodles','甜品':'Dessert','咖啡':'Coffee','正餐':'Dining','烧烤':'Barbecue','火锅':'Hot pot','餐厅':'Dining','美食':'Food','饮品':'Drinks','甜品店':'Dessert','咖啡店':'Coffee'};
export function categoryLabel(value){return categories[value]||(/^[\x20-\x7e]{1,40}$/.test(String(value))?String(value):'Food');}
export function normalizeFeed(data){if(!data||data.schemaVersion!==1||!Array.isArray(data.spots)||data.spots.length>5000)throw new Error('Invalid public venue collection');return data.spots.filter(p=>p&&typeof p.name==='string'&&typeof p.city==='string'&&(p.coordinateSystem??data.coordinateSystem)==='GCJ-02'&&Number.isFinite(p.lng)&&Number.isFinite(p.lat)&&p.lng>=-180&&p.lng<=180&&p.lat>=-90&&p.lat<=90).map(p=>({id:String(p.id),name:p.name.slice(0,160),city:p.city.slice(0,100),address:String(p.address||'').slice(0,250),category:categoryLabel(p.category),lng:p.lng,lat:p.lat,articleUrl:safeHttps(p.articleUrl),sourceName:p.source?.jsonUrl==='https://frostmoonrui.com/food-map/index.json'?'frostmoon-rui':'CacheTide'}));}
export function mergeFeeds(local,remote){const rows=[...normalizeFeed(local),...normalizeFeed(remote)],seen=new Set();return rows.filter(p=>{const key=JSON.stringify([p.name.normalize('NFKC').toLowerCase(),p.city,p.lng.toFixed(5),p.lat.toFixed(5)]);if(seen.has(key))return false;seen.add(key);p.id=p.sourceName+':'+p.id;return true;});}
export function filtered(rows,query='',city='',category=''){const q=query.trim().toLocaleLowerCase();return rows.filter(p=>(!city||p.city===city)&&(!category||p.category===category)&&(!q||[p.name,p.city,p.address,p.category].join(' ').toLocaleLowerCase().includes(q)));}
export function amapLink(p){return 'https://uri.amap.com/marker?'+new URLSearchParams({position:`${p.lng},${p.lat}`,name:p.name,coordinate:'gaode',src:'frostmoonrui'});}
function offset(lng,lat){const x=lng-105,y=lat-35,pi=Math.PI;let a=-100+2*x+3*y+.2*y*y+.1*x*y+.2*Math.sqrt(Math.abs(x));a+=(20*Math.sin(6*x*pi)+20*Math.sin(2*x*pi))*2/3;a+=(20*Math.sin(y*pi)+40*Math.sin(y*pi/3))*2/3;a+=(160*Math.sin(y*pi/12)+320*Math.sin(y*pi/30))*2/3;let b=300+x+2*y+.1*x*x+.1*x*y+.1*Math.sqrt(Math.abs(x));b+=(20*Math.sin(6*x*pi)+20*Math.sin(2*x*pi))*2/3;b+=(20*Math.sin(x*pi)+40*Math.sin(x*pi/3))*2/3;b+=(150*Math.sin(x*pi/12)+300*Math.sin(x*pi/30))*2/3;const rad=lat/180*pi,s=Math.sin(rad),magic=1-.006693421622965943*s*s,root=Math.sqrt(magic);return [b*180/(6378245/root*Math.cos(rad)*pi),a*180/((6378245*(1-.006693421622965943))/(magic*root)*pi)];}
export function toWgs84(lng,lat){if(lng<72.004||lng>137.8347||lat<.8293||lat>55.8271)return [lat,lng];let x=lng,y=lat;for(let i=0;i<5;i++){const [dx,dy]=offset(x,y);x=lng-dx;y=lat-dy;}return [y,x];}
